55	                    ss = (ss >= NSTREAM_INT - samplesPerRead) ? (ss + samplesPerRead - NSTREAM_INT)
56	                                                              : (ss + samplesPerRead);
57	                }
58	            else {
59	                (val3, val2, val1, val0) = mem[n][samp];
60	                if (ss == NSTREAM_INT - 1) {
61	                    buff[n][NSTREAM_INT - 1][dd] = val0;
62	                    buff[n][0][dd + 1] = val1;
63	                    buff[n][1][dd + 1] = val2;
64	                    buff[n][2][dd + 1] = val3;
65	                } else if (ss == NSTREAM_INT - 2) {
66	                    buff[n][NSTREAM_INT - 2][dd] = val0;
67	                    buff[n][NSTREAM_INT - 1][dd] = val1;
68	                    buff[n][0][dd + 1] = val2;
69	                    buff[n][1][dd + 1] = val3;
