73	                    buff[n][NSTREAM_INT - 1][dd] = val2;
74	                    buff[n][0][dd + 1] = val3;
75	                } else {
76	                    buff[n][ss][dd] = val0;
77	                    buff[n][ss + 1][dd] = val1;
78	                    buff[n][ss + 2][dd] = val2;
79	                    buff[n][ss + 3][dd] = val3;
80	                }
81	
82	                // Advance:
