90	void mm2s_str1(TT_DATA mem[NITER][memSizeAct],
91	               TT_STREAM sig_o[NSTREAM_INT]) // memSizeAct = 256;  2*memSizeAct/NSTREAM_INT = 128
92	{
93	LOAD_NITER:
94	    for (int n = 0; n < NITER; n++) {
95	    LOAD_SAMP:
96	        for (int samp = 0, dd = 0, ss = 0; samp < (memSizeAct); samp += 1) {
97	#pragma HLS pipeline II = 1
98	            sig_o[0].write(mem[n][samp]);
99	        }
100	    }
101	}
