107	void transmit(TT_SAMPLE (&buff)[NITER][NSTREAM_INT][(samplesPerRead * memSizeAct) / NSTREAM_INT],
108	              TT_STREAM sig_o[NSTREAM_INT]) {
109	REPEAT:
110	    for (int nn = 0; nn < NITER; nn++) { // 4
111	    RUN_DEPTH:
112	        for (int cc = 0, rr = 0, dd = 0; cc < (samplesPerRead * memSizeAct) / NSTREAM_INT; cc += samplesPerRead) {
113	#pragma HLS PIPELINE II = 1
114	        STREAM1:
115	            for (int ss = 0; ss < NSTREAM_INT; ss++) {
116	                TT_SAMPLE val0 = buff[nn][ss][cc];
117	                TT_SAMPLE val1 = buff[nn][ss][cc + 1];
118	                if
119	                    constexpr(samplesPerRead == 2) { sig_o[ss].write((val1, val0)); }
120	                else {
121	                    TT_SAMPLE val0 = buff[nn][ss][cc];
122	                    TT_SAMPLE val1 = buff[nn][ss][cc + 1];
123	                    TT_SAMPLE val2 = buff[nn][ss][cc + 2];
124	                    TT_SAMPLE val3 = buff[nn][ss][cc + 3];
125	                    // printf("buff[%d][%d][%d] = %d, %d\n", nn, ss, cc, buff[nn][ss][cc] >>16, buff[nn][ss][cc] %
