26	void capture_streams(TT_SAMPLE (&buff)[NITER][NSTREAM_INT][(memSizeAct * samplesPerRead) / NSTREAM_INT],
27	                     TT_STREAM sig_i[NSTREAM_INT]) {
28	// Incoming samples arriving down columns:
29	CAPTURE:
30	    for (int ll = 0; ll < NITER; ll++) {
31	        for (int cc = 0, addr = 0; cc < (memSizeAct) / NSTREAM_INT; cc++) {
32	#pragma HLS pipeline II = 1
33	            for (int ss = 0; ss < NSTREAM_INT; ss++) {
