104	// ------------------------------------------------------------
105	// Used for streams=1
106	// ------------------------------------------------------------
107	
108	void s2mm_str1(TT_DATA mem[NITER][memSizeAct], TT_STREAM sig_i[NSTREAM_INT]) {
109	    for (int nn = 0; nn < NITER; nn++) {
110	        for (int rr = 0, mm = 0; rr < memSizeAct; rr++) {
111	#pragma HLS PIPELINE II = 1
112	            mem[nn][mm++] = sig_i[0].read();
113	        }
114	    }
115	}
116	// ------------------------------------------------------------
117	// Wrapper
118	// ------------------------------------------------------------
119	
120	void s2mm_wrapper(s2mm::TT_DATA mem[NITER][memSizeAct], s2mm::TT_STREAM sig_i[NSTREAM_INT])
121	
122	{
123	#pragma HLS interface m_axi port = mem bundle = gmem offset = slave depth = NITER * memSizeAct
124	#pragma HLS interface axis port = sig_i
125	#pragma HLS interface s_axilite port = mem bundle = control
126	#pragma HLS interface s_axilite port = return bundle = control
127	#pragma HLS DATAFLOW
128	
129	    TT_SAMPLE buff[NITER][NSTREAM_INT][(memSizeAct * samplesPerRead) / NSTREAM_INT];
130	
131	#pragma HLS array_partition variable = buff dim = 1
132	#pragma HLS array_partition variable = buff dim = 2
133	#pragma HLS bind_storage variable = buff type = RAM_T2P impl = bram
134	#pragma HLS dependence variable = buff type = intra false
135	
136	    if (NSTREAM_INT != 1) {
137	        // Front end load from DDR4 to PL BRAM:
138	        capture_streams(buff, sig_i);
139	
140	        // Back end transmit from PL BRAM to AIE:
141	        read_buffer(mem, buff);
142	    } else {
143	        s2mm_str1(mem, sig_i);
144	    }
145	}
