34	namespace data_mover {
35	namespace details {
36	
37	/**
38	 * A bit more about manual burst / write design
39	 * Both take "request params + data" and operate on burst_maxi
40	 * Both will act like "request at first, close request later"
41	 * This means there'll be requests on the fly, and they need buffer.
42	 *
43	 * One important limit to be noticed:
44	 * burst maxi port will first "cut" request into sub request, if data request ran across 4KB border.
45	 * Outstanding are upperbound of such sub request, in pragma for burst maxi port
46	 * To avoid deadlock caused by sending too much request, request from HLS side need to be less than outstanding.
47	 *
48	 * In actual design, burst maxi width is no bigger than 64 Bytes (512 bits).
49	 * If BURSTLEN <= 64, then total size of one quest is less than 64 * 64 = 4096 Byte
50	 * So actual sub request is at most twice as much as request from HLS side.
51	 * So we could at least create (outstanding / 2) HLS requests is safe to be handled.
52	 *
53	 * But BURSTLEN should not be too small, for best bandwidth, at least 16.
54	 */
55	
56	/**
57	 * Read from stream and create burst write request to DDR/HBM
58	 *
59	 * @tparam WDATA width of MAXI port.
60	 * @tparam LATENCY latency of MAXI port.
61	 * @tparam OUTSTANDING read outstanding of MAXI port, should be less than 512.
62	 * @tparam BURSTLEN read burst length of MAXI port, should be less than 64.
63	 *
64	 * @param r_offset, stream to get offset for burst write
65	 * @param r_burst, stream ot get length for burst write, should be no bigger BURSTLEN
66	 * @param e_r, end of write request
67	 * @param w_data, stream to read data for writing
68	 * @param data MAXI port for writing
69	 */
70	
71	template <int WDATA, int LATENCY, int OUTSTANDING, int BURSTLEN>
72	void manualBurstWrite( // input
73	    hls::stream<ap_uint<64> >& r_offset,
74	    hls::stream<ap_uint<10> >& r_burst,
75	    hls::stream<bool>& e_r,
76	    hls::stream<ap_axiu<WDATA, 0, 0, 0> >& w_data,
77	    // output
78	    hls::burst_maxi<ap_uint<WDATA> >& data) {
79	    ap_uint<LATENCY> check = 0;
80	    ap_uint<10> req_left = OUTSTANDING / 2;
81	    ap_uint<10> write_left = 0;
82	    ap_uint<10> burst_record[1024];
83	    ap_uint<10> rec_head = 0;
84	    ap_uint<10> rec_tail = 0;
85	    bool last = e_r.read();
86	
87	ACC_BURST_REQ_LOOP:
88	    // TODO: accumulate so many request at first might cause deadlock, to be fixed.
89	    while (!last && rec_tail != OUTSTANDING / 2) {
90	#pragma HLS pipeline II = 1
91	        ap_uint<64> tmp_offset = r_offset.read();
92	        ap_uint<64> tmp_burst = r_burst.read();
93	        last = e_r.read();
94	        burst_record[rec_tail++] = tmp_burst;
95	        data.write_request(tmp_offset, tmp_burst);
96	        req_left--;
97	    }
98	    if (rec_tail != 0) {
99	        write_left = burst_record[rec_head++];
100	    }
101	
102	BURST_WRITE_LOOP:
103	    while (!last || write_left != 0 || rec_head != rec_tail) {
104	#pragma HLS pipeline II = 1
105	        bool check_l = check[LATENCY - 1];
106	        check <<= 1;
107	
108	        if (write_left != 0) { // load data and write if possible
109	            ap_axiu<WDATA, 0, 0, 0> tmp_data = w_data.read();
110	            data.write(tmp_data.data); // haha, too many data
111	
112	            if (--write_left == 0) { // if all data of current write request has been sent
113	                check[0] = 1;
114	                if (rec_head != rec_tail) {
115	                    write_left = burst_record[rec_head++];
116	                }
117	            }
118	        }
119	
120	        if (check_l) { // if a write request has become old enough
121	            data.write_response();
122	
123	            if (!last) {
124	                ap_uint<64> tmp_offset = r_offset.read();
125	                ap_uint<64> tmp_burst = r_burst.read();
126	                last = e_r.read();
127	                burst_record[rec_tail++] = tmp_burst;
128	                data.write_request(tmp_offset, tmp_burst);
129	            } else {
130	                req_left++;
131	            }
132	        }
133	    }
134	
135	    while (check != 0) {
136	        bool check_l = check[LATENCY - 1];
137	        check <<= 1;
138	        if (check_l) {
139	            data.write_response();
140	            req_left--;
141	        }
142	    }
143	}
144	
145	/**
146	 * Create burst read request to DDR/HBM and write to stream
147	 *
148	 * @tparam WDATA width of MAXI port.
149	 * @tparam LATENCY latency of MAXI port.
150	 * @tparam OUTSTANDING read outstanding of MAXI port, should be less than 512.
151	 * @tparam BURSTLEN read burst length of MAXI port, should be less than 64.
152	 *
153	 * @param data MAXI port for reading
154	 * @param r_offset, stream to get offset for burst read
155	 * @param r_burst, stream ot get length for burst read, should be no bigger BURSTLEN
156	 * @param e_r, end of read request
157	 * @param w_data, stream to write read result
158	 */
159	
160	template <int WDATA, int LATENCY, int OUTSTANDING, int BURSTLEN>
161	void manualBurstRead( // input
162	    hls::burst_maxi<ap_uint<WDATA> >& data,
163	    hls::stream<ap_uint<64> >& r_offset,
164	    hls::stream<ap_uint<10> >& r_burst,
165	    hls::stream<bool>& e_r,
166	    // output
167	    hls::stream<ap_axiu<WDATA, 0, 0, 0> >& w_data) {
168	    ap_uint<LATENCY> check = 0;             // delay check
169	    ap_uint<10> req_left = OUTSTANDING / 2; // how many more request could be issued, "/2" is to avoid hang
170	    ap_uint<10> req_ready = 0;              // how many request should be ready, according to delay check
171	    ap_uint<10> burst_record[1024];         // burstlen record
172	    ap_uint<10> rec_head = 0;               // record head
173	    ap_uint<10> rec_tail = 0;               // record tail
174	    ap_uint<10> read_left = 0;              // read left in 1 burst
175	    bool last = e_r.read();
176	
177	BURST_READ_LOOP:
178	    while (!last || req_ready != 0 || check != 0) {
179	#pragma HLS pipeline II = 1
180	        //#pragma HLS pipeline II = 1
181	
182	        bool check_l = check[LATENCY - 1];
183	        check <<= 1;
184	
185	        if (req_left != 0 && !last) { // if read outstanding is not exhausted, issue more request
186	            ap_uint<64> tmp_offset = r_offset.read();
187	            ap_uint<10> tmp_burst = r_burst.read();
188	            last = e_r.read();
189	
190	            data.read_request(tmp_offset, tmp_burst);
191	            check[0] = 1;
192	            req_left--;
193	            burst_record[rec_tail++] = tmp_burst;
194	        }
195	
196	        if (req_ready != 0 || read_left != 0) { // if there's mature req
197	            if (read_left == 0) {
198	                read_left = burst_record[rec_head++] - 1;
199	                req_ready--;
200	                req_left++;
201	            } else {
202	                read_left--;
203	            }
204	
205	            ap_axiu<WDATA, 0, 0, 0> tmp_data;
206	            tmp_data.data = data.read();
207	            tmp_data.keep = -1;
208	            tmp_data.last = 0;
209	            w_data.write(tmp_data);
210	        }
211	
212	        if (check_l) { // if a new request has become old enough
213	            req_ready++;
214	        }
215	    }
216	
217	    while (read_left != 0) {
218	#pragma HLS pipeline II = 1
219	        ap_axiu<WDATA, 0, 0, 0> tmp_data;
220	        tmp_data.data = data.read();
221	        tmp_data.keep = -1;
222	        tmp_data.last = 0;
223	        read_left--;
224	        w_data.write(tmp_data);
225	    }
226	}
227	
228	template <int BURSTLEN>
229	void cmdParser(hls::burst_maxi<ap_uint<64> > descriptor,
230	               hls::stream<ap_uint<64> >& r_offset,
231	               hls::stream<ap_uint<10> >& r_burst,
232	               hls::stream<bool>& e_r) {
233	    descriptor.read_request(0, 1);
234	    ap_uint<64> cmd_nums = descriptor.read();
235	    ap_uint<64> cmd_buf_ptr = 1;
236	
237	    // if (cmd_nums != 0) {
238	    //    descriptor.read_request(cmd_buf_ptr, 9);
239	    //}
240	
241	    for (int cmd_idx = 0; cmd_idx < cmd_nums; cmd_idx++) {
242	        descriptor.read_request(cmd_buf_ptr, 9);
243	        ap_uint<64> cfg[9];
244	        for (int i = 0; i < 9; i++) {
245	            cfg[i] = descriptor.read();
246	        }
247	        cmd_buf_ptr += 9;
248	        // descriptor.read_request(cmd_buf_ptr, 9);
249	
250	        ap_uint<64>& offset = cfg[0];
251	        ap_uint<64>& i1 = cfg[1];
252	        ap_uint<64>& d1 = cfg[2];
253	        ap_uint<64>& i2 = cfg[3];
254	        ap_uint<64>& d2 = cfg[4];
255	        ap_uint<64>& i3 = cfg[5];
256	        ap_uint<64>& d3 = cfg[6];
257	        ap_uint<64>& i4 = cfg[7];
258	        ap_uint<64>& d4 = cfg[8];
259	
260	        ap_uint<64> x_inc;
261	        if (i1 == 1) {
262	            x_inc = BURSTLEN;
263	        } else {
264	            x_inc = 1;
265	        }
266	
267	        for (ap_uint<64> w = 0; w < d4; w++) {
268	            ap_uint<64> s4 = offset + w * i4;
269	            for (ap_uint<64> z = 0; z < d3; z++) {
270	                ap_uint<64> s3 = s4 + z * i3;
271	                for (ap_uint<64> y = 0; y < d2; y++) {
272	                    ap_uint<64> s2 = s3 + y * i2;
273	                    for (ap_uint<64> x = 0; x < d1; x += x_inc) {
274	#pragma HLS pipeline II = 1
275	                        ap_uint<64> s1 = s2 + x * i1;
276	
277	                        ap_uint<10> burst;
278	                        if (i1 == 1) {
279	                            if ((x + BURSTLEN) <= d1) {
280	                                burst = BURSTLEN;
281	                            } else {
282	                                burst = d1 - x;
283	                            }
284	                        } else {
285	                            burst = 1;
286	                        }
287	
288	                        r_offset.write(s1);
289	                        r_burst.write(burst);
290	                        e_r.write(false);
291	                    }
292	                }
293	            }
294	        }
295	    }
296	    e_r.write(true);
297	}
298	} // namespace details
299	
300	/**
301	 * @brief data_mover for reading multiple 4D cuboids.
302	 * It will read the descriptors, access data as descriptors demand and feed data to AXI stream.
303	 * Descriptors are stored in descriptor buffer, which starts with 64 bit integer which represent number of descriptors
304	 * inside the buffer. It's followed by one or multiple descritpors, each of which consists 9 x 64bits interger, cfg[0],
305	 * cfg[1] .. cfg[8].
306	 * All descriptors will be processed one by one, from the first to the last.
307	 * Each descriptor represent the access pattern of 4D cuboid, which could be treated like a 4-layer nested loop.
308	 * Please take reference from design internal doc page for details of descriptor format.
309	 *
310	 * @tparam WDATA Bit width of data element
311	 * @tparam LATENCY MAXI port latency, should be the same with pragma setup
312	 * @tparam OUTSTANDING MAXI port read/write outstanding, should be the same with pragma setup
313	 * @tparam BURSTLEN MAXI port read/write burst length, should be the same with pragma setup
314	 *
315	 * @param descriptor_buffer Buffer that stores one or multiple descriptors.
316	 * @param data Buffer that contains data to be accessed
317	 * @param w_data AXI Stream which data will be written to.
318	 */
319	
320	template <int WDATA, int LATENCY, int OUTSTANDING, int BURSTLEN>
321	void read4D(
322	    // input
323	    hls::burst_maxi<ap_uint<64> >& descriptor_buffer,
324	    hls::burst_maxi<ap_uint<WDATA> >& data,
325	    // ouput
326	    hls::stream<ap_axiu<WDATA, 0, 0, 0> >& w_data) {
327	#pragma HLS dataflow
328	    hls::stream<ap_uint<64> > r_offset("r_offset");
329	#pragma HLS stream variable = r_offset depth = OUTSTANDING
330	    hls::stream<ap_uint<10> > r_burst("r_burst");
331	#pragma HLS stream variable = r_burst depth = OUTSTANDING
332	    hls::stream<bool> e_r("e_r");
333	#pragma HLS stream variable = e_r depth = OUTSTANDING
334	
335	    details::cmdParser<BURSTLEN>(descriptor_buffer, r_offset, r_burst, e_r);
336	    details::manualBurstRead<WDATA, LATENCY, OUTSTANDING, BURSTLEN>(data, r_offset, r_burst, e_r, w_data);
337	}
338	
339	/**
340	 * @brief data_mover for write multiple 4D cuboids.
341	 * It will read data from AXI stream, write access data to the address as descriptors demand.
342	 * Descriptors are stored in descriptor buffer, which starts with 64 bit integer which represent number of descriptors
343	 * inside the buffer. It's followed by one or multiple descritpors, each of which consists 9 x 64bits interger, cfg[0],
344	 * cfg[1] .. cfg[8].
345	 * All descriptors will be processed one by one, from the first to the last.
346	 * Each descriptor represent the access pattern of 4D cuboid, which could be treated like a 4-layer nested loop.
347	 * Please take reference from design internal doc page for details of descriptor format.
348	 *
349	 * @tparam WDATA Bit width of data element
350	 * @tparam LATENCY MAXI port latency, should be the same with pragma setup
351	 * @tparam OUTSTANDING MAXI port read/write outstanding, should be the same with pragma setup
352	 * @tparam BURSTLEN MAXI port read/write burst length, should be the same with pragma setup
353	 *
354	 * @param descriptor_buffer Buffer that stores one or multiple descriptors.
355	 * @param w_data AXI Stream which data will be written to.
356	 * @param data Buffer that contains data to be accessed
357	 */
358	
359	template <int WDATA, int LATENCY, int OUTSTANDING, int BURSTLEN>
360	void write4D(
361	    // input
362	    hls::burst_maxi<ap_uint<64> >& descriptor_buffer,
363	    hls::stream<ap_axiu<WDATA, 0, 0, 0> >& w_data,
364	    // ouput
365	    hls::burst_maxi<ap_uint<WDATA> >& data) {
366	#pragma HLS dataflow
367	    hls::stream<ap_uint<64> > r_offset("r_offset");
368	#pragma HLS stream variable = r_offset depth = OUTSTANDING
369	    hls::stream<ap_uint<10> > r_burst("r_burst");
370	#pragma HLS stream variable = r_burst depth = OUTSTANDING
371	    hls::stream<bool> e_r("e_r");
372	#pragma HLS stream variable = e_r depth = OUTSTANDING
373	
374	    details::cmdParser<BURSTLEN>(descriptor_buffer, r_offset, r_burst, e_r);
375	    details::manualBurstWrite<WDATA, LATENCY, OUTSTANDING, BURSTLEN>(r_offset, r_burst, e_r, w_data, data);
376	}
377	
378	} // namespace data_mover
379	} // namespace xf
380	
381	#endif
