40	/**
41	 * Load 4D pattern and program memory
42	 *
43	 * @tparam W width of AXI-master/URAM/AXI-stream port
44	 *
45	 * @param pattern_0, 4D pattern for AXIM-side mover
46	 * @param pattern_1, 4D pattern for AXIS-side mover
47	 * @param pm_0, program memory for AXIM-side mover
48	 * @param pm_1, program memory for AXIS-side mover
49	 */
50	template <int W>
51	void load_cfg(hls::burst_maxi<ap_uint<W> > cfg_port,
52	              ap_uint<32>* pattern_0,
53	              ap_uint<32>* pattern_1,
54	              ap_uint<32>* pm_0,
55	              ap_uint<32>* pm_1) {
56	    const int elem_of_word = W / 32;
57	
58	    ap_uint<32> rd_ptr = 0;
59	    for (ap_uint<3> t = 0; t < 4; t++) {
60	        ap_uint<32>* target;
61	        switch (t) {
62	            case 0: {
63	                target = pattern_0;
64	                break;
65	            }
66	            case 1: {
67	                target = pattern_1;
68	                break;
69	            }
70	            case 2: {
71	                target = pm_0;
72	                break;
73	            }
74	            case 3: {
75	                target = pm_1;
76	                break;
77	            }
78	        }
79	
80	        // load header
81	        cfg_port.read_request(rd_ptr++, 1);
82	        ap_uint<W> num_of_cmd = cfg_port.read();
83	        ap_uint<32> nread = (num_of_cmd + elem_of_word - 1) / elem_of_word;
84	        cfg_port.read_request(rd_ptr, nread);
85	        rd_ptr += nread;
86	
87	        ap_uint<8> idx = 0;
88	        ap_uint<16> wr_ptr = 0;
89	        ap_uint<W> word;
90	    LOAD_CFG_CORE_LOOP:
91	        for (int i = 0; i < num_of_cmd; i++) {
92	#pragma HLS pipeline II = 1
93	            //#pragma HLS unroll factor = 2
94	            if (idx == 0) word = cfg_port.read();
95	            target[wr_ptr++] = word(idx * 32 + 31, idx * 32);
96	
97	            if (idx == elem_of_word - 1)
98	                idx = 0;
99	            else
100	                idx++;
101	        }
102	    }
103	}
