105	/**
106	 * The core of Read DM, read data from DDR/HBM and forward to AXI-stream
107	 *
108	 * @tparam WDATA width of AXI-master/URAM/AXI-stream port
109	 * @tparam CACHE_DEPTH depth of external URAM.
110	 * @tparam LATENCY latency of MAXI port.
111	 * @tparam BURST_LEN burst length of MAXI port.
112	 * @tparam OUTSTANDING read outstanding of MAXI port, should be less than 512.
113	 *
114	 * @param maxi_port, AXI-master port
115	 * @param pattern_0, 4D pattern for AXIM-side mover
116	 * @param pattern_1, 4D pattern for AXIS-side mover
117	 * @param pm_0, program memory for AXIM-side mover
118	 * @param pm_1, program memory for AXIS-side mover
119	 * @param i_sync_strm, input sync singal from other DM
120	 * @param o_sync_strm, output sync singal to other DM
121	 * @param o_axis_strm, AXI-stream output
122	 */
123	template <int WDATA, int CACHE_DEPTH, int LATENCY, int BURST_LEN, int OUTSTANDING>
124	void read_4D(hls::burst_maxi<ap_uint<WDATA> > maxi_port,
125	             ap_uint<32>* pattern_0,
126	             ap_uint<32>* pattern_1,
127	             ap_uint<32>* pm_0,
128	             ap_uint<32>* pm_1,
129	             hls::stream<ap_axiu<8 + 8, 0, 0, 0> >& i_sync_strm,
130	             hls::stream<ap_axiu<8 + 8, 0, 0, 0> >& o_sync_strm,
131	             hls::stream<ap_axiu<WDATA, 0, 0, 0> >& o_axis_strm) {
132	#pragma HLS dataflow
133	    hls::stream<ap_uint<8>, 8> ctrl0_ack_strm;
134	    hls::stream<ap_uint<8>, 8> ctrl0_pattern_strm;
135	    hls::stream<ap_uint<8>, 8> ctrl_sync_s2m_strm;
136	    hls::stream<ap_uint<8>, 8> ctrl_sync_m2s_strm;
137	    hls::stream<ap_uint<32>, 32> uram_waddr_strm;
138	#pragma HLS bind_storage variable = uram_waddr_strm type = FIFO impl = lutram
139	    hls::stream<ap_uint<WDATA>, 32> uram_wdata_strm;
140	#pragma HLS bind_storage variable = uram_wdata_strm type = FIFO impl = lutram
141	
142	    dm_ctrl_axim(pm_0, ctrl0_ack_strm, ctrl_sync_s2m_strm, i_sync_strm, ctrl0_pattern_strm, ctrl_sync_m2s_strm,
143	                 o_sync_strm);
144	    axim_to_uram<WDATA, CACHE_DEPTH, LATENCY, BURST_LEN, OUTSTANDING>(maxi_port, pattern_0, ctrl0_pattern_strm,
145	                                                                      ctrl0_ack_strm, uram_waddr_strm, uram_wdata_strm);
146	
147	    hls::stream<ap_uint<8>, 8> ctrl1_ack_strm;
148	    hls::stream<ap_uint<8>, 8> ctrl1_pattern_strm;
149	
150	    dm_ctrl_axis(pm_1, ctrl1_ack_strm, ctrl_sync_m2s_strm, ctrl1_pattern_strm, ctrl_sync_s2m_strm);
151	    uram_to_axis<WDATA, CACHE_DEPTH>(uram_waddr_strm, uram_wdata_strm, pattern_1, ctrl1_pattern_strm, ctrl1_ack_strm,
152	                                     o_axis_strm);
153	}
