194	    uram_to_axim<WDATA, CACHE_DEPTH, LATENCY, BURST_LEN, OUTSTANDING>(maxi_port, pattern_0, ctrl0_pattern_strm,
195	                                                                      uram_rdata_strm, uram_raddr_strm, ctrl0_ack_strm);
196	
197	    hls::stream<ap_uint<8>, 8> ctrl1_ack_strm;
198	    hls::stream<ap_uint<8>, 8> ctrl1_pattern_strm;
