207	/**
208	 * The top wrapper of Read DM, read data from DDR/HBM and forward to AXI-stream
209	 *
210	 * @tparam WDATA width of AXI-master/URAM/AXI-stream port
211	 * @tparam CACHE_DEPTH depth of external URAM.
212	 * @tparam LATENCY latency of MAXI port.
213	 * @tparam BURST_LEN burst length of MAXI port.
214	 * @tparam OUTSTANDING read outstanding of MAXI port, should be less than 512.
215	 *
216	 * @param cfg_port, AXI-master port for congfiguration
217	 * @param data_port, AXI-master port for data movement
218	 * @param i_sync_strm, input sync singal from other DM
219	 * @param o_sync_strm, output sync singal to other DM
220	 * @param o_axis_strm, AXI-stream output
221	 */
222	template <int WDATA, int CACHE_DEPTH, int LATENCY, int BURST_LEN, int OUTSTANDING>
223	void ddr_to_stream(hls::burst_maxi<ap_uint<WDATA> > cfg_port,
224	                   hls::burst_maxi<ap_uint<WDATA> > data_port,
225	                   hls::stream<ap_axiu<8 + 8, 0, 0, 0> >& i_sync_strm,
226	                   hls::stream<ap_axiu<8 + 8, 0, 0, 0> >& o_sync_strm,
227	                   hls::stream<ap_axiu<WDATA, 0, 0, 0> >& o_axis_strm) {
228	    ap_uint<32> pattern_m2s[1024];
229	    ap_uint<32> pattern_s2s[1024];
230	    ap_uint<32> pm_m2s[1024];
231	    ap_uint<32> pm_s2s[1024];
232	#pragma HLS bind_storage variable = pattern_m2s type = RAM_2P impl = bram
233	#pragma HLS bind_storage variable = pattern_s2s type = RAM_2P impl = bram
234	#pragma HLS bind_storage variable = pm_m2s type = RAM_2P impl = bram
235	#pragma HLS bind_storage variable = pm_s2s type = RAM_2P impl = bram
236	    // load program & pattern
237	    details::load_cfg<WDATA>(cfg_port, pattern_m2s, pattern_s2s, pm_m2s, pm_s2s);
238	    // Emit the pattern
239	    details::read_4D<WDATA, CACHE_DEPTH, LATENCY, BURST_LEN, OUTSTANDING>(
