28	/**
29	 * Load from AXI master, and send data to stream.
30	 *
31	 * It is expected that the size is aligned with (WM/8) and (WS/8),
32	 * otherwise out-of-boundary data would be read/written.
33	 *
34	 * @tparam WM width of AXI master.
35	 * @tparam WS width of AXI stream.
36	 * @tparam BLEN burst length when reading from AXI master.
37	 *
38	 * @param mm master port.
39	 * @param s stream port.
40	 * @param size size of data to be loaded, in byte.
41	 */
42	template <int WM, int WS, int BLEN = 32>
43	void loadMasterToStream(ap_uint<WM>* mm, hls::stream<ap_axiu<WS, 0, 0, 0> >& s, uint64_t size) {
44	#ifndef __SYNTHESIS__
45	    static_assert(WM == WS, "WM should be equal to WS in the current implementation");
46	#endif
47	    const int bytePerData = WM / 8;
48	    const int nBlks = size / bytePerData + ((size % bytePerData) > 0);
49	    const int nBurst = nBlks / BLEN;
50	    int cnt = 0;
51	    for (int i = 0; i < nBurst; i++) {
52	        for (int j = 0; j < BLEN; j++) {
53	#pragma HLS pipeline II = 1
54	            ap_axiu<WS, 0, 0, 0> tmp;
55	            tmp.data = mm[cnt];
56	            tmp.keep = -1;
57	            tmp.last = 0;
58	            s.write(tmp);
59	            cnt++;
60	        }
61	    }
62	    int leftBlks = nBlks % BLEN;
63	    if (leftBlks > 0) {
64	        for (int i = 0; i < leftBlks; i++) {
65	#pragma HLS pipeline II = 1
66	            ap_axiu<WS, 0, 0, 0> tmp;
67	            tmp.data = mm[cnt];
68	            tmp.keep = -1;
69	            tmp.last = 0;
70	            s.write(tmp);
71	            cnt++;
72	        }
73	    }
74	}
75	
76	/**
77	 * Load from AXI master, and send data to stream.
78	 *
79	 * It is expected that the size is aligned with (WM/8) and (WS/8),
80	 * otherwise out-of-boundary data would be read/written.
81	 *
82	 * @tparam WM width of AXI master.
83	 * @tparam WS width of AXI stream.
84	 * @tparam BLEN burst length when reading from AXI master.
85	 *
86	 * @param mm master port.
87	 * @param s stream port.
88	 * @param size size of data to be loaded, in byte.
89	 * @param vld_str stream port, to record the start and end position of loading data from AXI master to stream.
90	 * @param cntData count data number that have been loaded from AXI master, in byte.
91	 */
92	template <int WM, int WS, int BLEN = 32>
93	void loadMasterToStream(ap_uint<WM>* mm,
94	                        hls::stream<ap_axiu<WS, 0, 0, 0> >& s,
95	                        uint64_t size,
96	                        hls::stream<ap_uint<1> >& vld_str,
97	                        uint64_t* cntData) {
98	#ifndef __SYNTHESIS__
99	    static_assert(WM == WS, "WM should be equal to WS in the current implementation");
100	#endif
101	    const int bytePerData = WM / 8;
102	    const int nBlks = size / bytePerData + ((size % bytePerData) > 0);
103	    const int nBurst = nBlks / BLEN;
104	    int cnt = 0;
105	    vld_str.write_nb(1);
106	    for (int i = 0; i < nBurst; i++) {
107	        for (int j = 0; j < BLEN; j++) {
108	#pragma HLS pipeline II = 1
109	            ap_axiu<WS, 0, 0, 0> tmp;
110	            tmp.data = mm[cnt];
111	            tmp.keep = -1;
112	            tmp.last = 0;
113	            s.write(tmp);
114	            cnt++;
115	        }
116	        *cntData = cnt * bytePerData;
117	    }
118	    int leftBlks = nBlks % BLEN;
119	    if (leftBlks > 0) {
120	        for (int i = 0; i < leftBlks; i++) {
121	#pragma HLS pipeline II = 1
122	            ap_axiu<WS, 0, 0, 0> tmp;
123	            tmp.data = mm[cnt];
124	            tmp.keep = -1;
125	            tmp.last = 0;
126	            s.write(tmp);
127	            cnt++;
128	        }
129	    }
130	    *cntData = cnt * bytePerData;
131	    vld_str.write_nb(1);
132	}
