118	/**
119	 * Load pattern and program memory for bi-DM
120	 *
121	 * @tparam W width of AXI-master/URAM/AXI-stream port
122	 *
123	 * @param cfg_port burst_maxi<> port of patterns and program memory
124	 * @param pattern_0 pattern for axis_to_uram
125	 * @param pattern_1 pattern for uram_to_axim
126	 * @param pattern_2 pattern for uram_to_axis
127	 * @param pattern_3 pattern for axim_to_uram
128	 * @param pm_0 program memory for ctrl of axis_to_uram
129	 * @param pm_1 program memory for ctrl of uram_to_axim
130	 * @param pm_2 program memory for ctrl of uram_to_axis
131	 * @param pm_3 program memory for ctrl of axim_to_uram
132	 */
133	template <int W>
134	void bi_load_cfg(hls::burst_maxi<ap_uint<W> > cfg_port,
135	                 ap_uint<32>* pattern_0,
136	                 ap_uint<32>* pattern_1,
137	                 ap_uint<32>* pattern_2,
138	                 ap_uint<32>* pattern_3,
139	                 ap_uint<32>* pm_0,
140	                 ap_uint<32>* pm_1,
141	                 ap_uint<32>* pm_2,
142	                 ap_uint<32>* pm_3) {
143	    const int elem_of_word = W / 32;
144	
145	    ap_uint<32> rd_ptr = 0;
146	    for (ap_uint<4> t = 0; t < 8; t++) {
147	        ap_uint<32>* target;
148	        switch (t) {
149	            case 0: {
150	                target = pattern_0;
151	                break;
152	            }
153	            case 1: {
154	                target = pattern_1;
155	                break;
156	            }
157	            case 2: {
158	                target = pattern_2;
159	                break;
160	            }
161	            case 3: {
162	                target = pattern_3;
163	                break;
164	            }
165	            case 4: {
166	                target = pm_0;
167	                break;
168	            }
169	            case 5: {
170	                target = pm_1;
171	                break;
172	            }
173	            case 6: {
174	                target = pm_2;
175	                break;
176	            }
177	            case 7: {
178	                target = pm_3;
179	                break;
180	            }
181	        }
182	
183	        // load header
184	        cfg_port.read_request(rd_ptr++, 1);
185	        ap_uint<W> num_of_cmd = cfg_port.read();
186	        ap_uint<32> nread = (num_of_cmd + elem_of_word - 1) / elem_of_word;
187	        cfg_port.read_request(rd_ptr, nread);
188	        rd_ptr += nread;
189	
190	        ap_uint<8> idx = 0;
191	        ap_uint<16> wr_ptr = 0;
192	        ap_uint<W> word;
193	    LOAD_CFG_CORE_LOOP:
194	        for (int i = 0; i < num_of_cmd; i++) {
195	#pragma HLS pipeline II = 1
196	            // #pragma HLS unroll factor = 2
197	            if (idx == 0) word = cfg_port.read();
198	            target[wr_ptr++] = word(idx * 32 + 31, idx * 32);
199	
200	            if (idx == elem_of_word - 1)
201	                idx = 0;
202	            else
203	                idx++;
204	        }
205	    }
206	}
