264	    hls::stream<ap_uint<8>, 8> c3_pattern_strm;
265	
266	/* for CSIM */
267	#ifndef __SYNTHESIS__
268	    std::cout << "## Test in CSIM_THREADS ##" << std::endl;
269	    hls::stream<ap_uint<8>, 32> c0_sync_i_intra_strm;
270	    hls::stream<ap_uint<8>, 32> c0_sync_o_intra_strm;
271	    hls::stream<ap_uint<8>, 32> c1_sync_i_intra_strm;
272	    hls::stream<ap_uint<8>, 32> c1_sync_o_intra_strm;
273	    hls::stream<ap_uint<8>, 32> c2_sync_i_intra_strm;
274	    hls::stream<ap_uint<8>, 32> c2_sync_o_intra_strm;
275	    hls::stream<ap_uint<8>, 32> c3_sync_i_intra_strm;
276	    hls::stream<ap_uint<8>, 32> c3_sync_o_intra_strm;
277	
278	    // ctrl-0
279	    RUN_IN_THREAD(bi_details::bi_alu, STD_REF(pm_0), STD_REF(c0_ack_strm), STD_REF(c0_sync_o_intra_strm),
280	                  STD_REF(c0_sync_i_intra_strm), STD_REF(c0_pattern_strm));
281	
282	    RUN_IN_THREAD(bi_details::bi_sync_dm, STD_REF(c0_sync_i_intra_strm), STD_REF(ctrl_sync_m2s_strm),
283	                  STD_REF(c0_sync_o_intra_strm), STD_REF(ctrl_sync_s2s_strm));
284	
285	    // ctrl-1
286	    RUN_IN_THREAD(bi_details::bi_alu, STD_REF(pm_1), STD_REF(c1_ack_strm), STD_REF(c1_sync_o_intra_strm),
287	                  STD_REF(c1_sync_i_intra_strm), STD_REF(c1_pattern_strm));
288	
289	    RUN_IN_THREAD(bi_details::bi_sync_dm, STD_REF(c1_sync_i_intra_strm), STD_REF(ctrl_sync_m2m_strm),
290	                  STD_REF(c1_sync_o_intra_strm), STD_REF(ctrl_sync_m2s_strm));
291	
292	    // ctrl-2
293	    RUN_IN_THREAD(bi_details::bi_alu, STD_REF(pm_2), STD_REF(c2_ack_strm), STD_REF(c2_sync_o_intra_strm),
294	                  STD_REF(c2_sync_i_intra_strm), STD_REF(c2_pattern_strm));
295	
296	    RUN_IN_THREAD(bi_details::bi_sync_dm, STD_REF(c2_sync_i_intra_strm), STD_REF(ctrl_sync_s2s_strm),
297	                  STD_REF(c2_sync_o_intra_strm), STD_REF(ctrl_sync_s2m_strm));
298	
299	    // ctrl-3
300	    RUN_IN_THREAD(bi_details::bi_alu, STD_REF(pm_3), STD_REF(c3_ack_strm), STD_REF(c3_sync_o_intra_strm),
301	                  STD_REF(c3_sync_i_intra_strm), STD_REF(c3_pattern_strm));
302	
303	    RUN_IN_THREAD(bi_details::bi_sync_dm, STD_REF(c3_sync_i_intra_strm), STD_REF(ctrl_sync_s2m_strm),
304	                  STD_REF(c3_sync_o_intra_strm), STD_REF(ctrl_sync_m2m_strm));
305	
306	    JOIN_THREADS();
307	
308	#else
309	    // bind storage
310	    hls::stream<ap_uint<32>, 32> s2u_waddr_strm("s2u_w_addr_strm");
311	    hls::stream<ap_uint<WDATA>, 64> s2u_wdata_strm("s2u_w_data_strm");
312	
313	    hls::stream<ap_uint<32>, 32> u2m_raddr_strm("u2m_r_addr_strm");
314	    hls::stream<ap_uint<WDATA>, 4096> u2m_rdata_strm("u2m_r_data_strm");
315	#pragma HLS bind_storage variable = u2m_rdata_strm type = FIFO impl = URAM
316	
317	    hls::stream<ap_uint<32>, 32> u2s_raddr_strm("u2s_r_addr_strm");
318	    hls::stream<ap_uint<WDATA>, 64> u2s_rdata_strm("u2s_r_data_strm");
319	
320	    hls::stream<ap_uint<32>, 32> m2u_waddr_strm("m2u_w_addr_strm");
321	    hls::stream<ap_uint<WDATA>, 64> m2u_wdata_strm("m2u_w_data_strm");
322	
323	#pragma HLS dataflow
324	    bi_details::bi_dm_ctrl(pm_0, c0_ack_strm, ctrl_sync_m2s_strm, ctrl_sync_s2s_strm, c0_pattern_strm);
325	    axis_to_uram<WDATA, CACHE_DEPTH>(i_axis_strm, pattern_0, c0_pattern_strm, s2u_waddr_strm, s2u_wdata_strm,
326	                                     c0_ack_strm);
327	
328	    bi_details::bi_dm_ctrl(pm_1, c1_ack_strm, ctrl_sync_m2m_strm, ctrl_sync_m2s_strm, c1_pattern_strm);
329	    uram_to_axim<WDATA, CACHE_DEPTH, LATENCY, BURST_LEN, OUTSTANDING>(o_maxi_port, pattern_1, c1_pattern_strm,
330	                                                                      u2m_raddr_strm, u2m_rdata_strm, c1_ack_strm);
331	
332	    bi_details::bi_dm_ctrl(pm_2, c2_ack_strm, ctrl_sync_s2s_strm, ctrl_sync_s2m_strm, c2_pattern_strm);
333	    uram_to_axis<WDATA, CACHE_DEPTH>(o_axis_strm, pattern_2, c2_pattern_strm, u2s_raddr_strm, u2s_rdata_strm,
334	                                     c2_ack_strm);
335	
336	    bi_details::bi_dm_ctrl(pm_3, c3_ack_strm, ctrl_sync_s2m_strm, ctrl_sync_m2m_strm, c3_pattern_strm);
337	    axim_to_uram<WDATA, CACHE_DEPTH, LATENCY, BURST_LEN, OUTSTANDING>(i_maxi_port, pattern_3, c3_pattern_strm,
338	                                                                      m2u_waddr_strm, m2u_wdata_strm, c3_ack_strm);
339	
340	    bi_uram_access<WDATA, CACHE_DEPTH>(s2u_waddr_strm, s2u_wdata_strm, m2u_waddr_strm, m2u_wdata_strm, u2s_raddr_strm,
341	                                       u2s_rdata_strm, u2m_raddr_strm, u2m_rdata_strm);
342	#endif
343	}
344	
345	/**
346	 * Top wrapper of Bi-directional DM, read data from AXI-stream and offload to DDR/HBM
347	 *
348	 * @tparam WDATA width of AXI-master/URAM/AXI-stream port
349	 * @tparam CACHE_DEPTH depth of external URAM.
350	 * @tparam LATENCY latency of MAXI port.
351	 * @tparam BURST_LEN burst length of MAXI port.
352	 * @tparam OUTSTANDING write outstanding of MAXI port, should be less than 512.
353	 *
354	 * @param cfg_port AXI-master port for congfiguration
355	 * @param i_maxi_port AXI-master port for data movement, from DDR to on-chip cache
356	 * @param o_maxi_port AXI-master port for data movement, from on-chip cache to DDR
357	 * @param i_axis_strm AXI-Stream port to load data from AXI-Stream to on-chip cache
358	 * @param o_axis_strm AXI-Stream port to forward data from on-chip cache to AXI-Stream
359	 */
360	template <int WDATA, int CACHE_DEPTH, int LATENCY, int BURST_LEN, int OUTSTANDING>
361	void bi_data_mover(hls::burst_maxi<ap_uint<WDATA> > cfg_port,
362	                   hls::burst_maxi<ap_uint<WDATA> > i_maxi_port,
363	                   hls::burst_maxi<ap_uint<WDATA> > o_maxi_port,
364	                   hls::stream<ap_axiu<WDATA, 0, 0, 0> >& i_axis_strm,
365	                   hls::stream<ap_axiu<WDATA, 0, 0, 0> >& o_axis_strm) {
366	    ap_uint<32> pattern_0[1024];
367	    ap_uint<32> pattern_1[1024];
368	    ap_uint<32> pattern_2[1024];
369	    ap_uint<32> pattern_3[1024];
370	    ap_uint<32> pm_0[1024];
371	    ap_uint<32> pm_1[1024];
372	    ap_uint<32> pm_2[1024];
373	    ap_uint<32> pm_3[1024];
374	#pragma HLS bind_storage variable = pattern_0 type = RAM_2P impl = bram
375	#pragma HLS bind_storage variable = pattern_1 type = RAM_2P impl = bram
376	#pragma HLS bind_storage variable = pattern_2 type = RAM_2P impl = bram
377	#pragma HLS bind_storage variable = pattern_3 type = RAM_2P impl = bram
378	#pragma HLS bind_storage variable = pm_0 type = RAM_2P impl = bram
379	#pragma HLS bind_storage variable = pm_1 type = RAM_2P impl = bram
380	#pragma HLS bind_storage variable = pm_2 type = RAM_2P impl = bram
381	#pragma HLS bind_storage variable = pm_3 type = RAM_2P impl = bram
382	    // load program & pattern
383	    bi_details::bi_load_cfg<WDATA>(cfg_port, pattern_0, pattern_1, pattern_2, pattern_3, pm_0, pm_1, pm_2, pm_3);
384	    // Emit the pattern
385	    bi_details::bi_dm<WDATA, CACHE_DEPTH, LATENCY, BURST_LEN, OUTSTANDING>(i_axis_strm, o_axis_strm, i_maxi_port,
386	                                                                           o_maxi_port, pattern_0, pattern_1, pattern_2,
387	                                                                           pattern_3, pm_0, pm_1, pm_2, pm_3);
388	}
389	
390	} // namespace bi_details
391	} // namespace data_mover
392	} // namespace xf
